import { useEffect, useState } from 'react';
import API from '../services/api';
import Sidebar from '../components/Sidebar';

function AlertsPage() {
    const [alerts, setAlerts] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAlerts = async () => {
            try {
                const response = await API.get('/alerts');
                setAlerts(response.data.alerts);
            } catch (error) {
                console.log(error);
            } finally {
                setLoading(false);
            }
        };

        fetchAlerts();

        // Poll for alerts just like the dashboard
        const interval = setInterval(() => {
            fetchAlerts();
        }, 5000);

        return () => clearInterval(interval);
    }, []);

    return (
        <div className="flex min-h-screen bg-surface text-on-surface font-inter">

            {/* SIDEBAR */}
            <Sidebar />

            {/* MAIN CONTENT AREA */}
            <div className="pl-72 flex-1">

                {/* TOP HEADER BAR */}
                <header className="fixed top-0 left-72 right-0 h-16 bg-surface-dim/70 backdrop-blur-2xl z-40 flex items-center justify-between px-6 border-b border-glass-stroke">
                    <div />
                    <div className="flex items-center gap-3 pl-4">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center">
                            <span className="material-symbols-outlined text-white text-[18px]">person</span>
                        </div>
                    </div>
                </header>

                <main className="pt-16 min-h-screen">
                    <div className="p-6">
                        <div className="flex justify-between items-end border-b border-glass-stroke pb-4 mb-6">
                            <div>
                                <h1 className="text-headline-lg font-inter text-on-surface">
                                    System Alerts
                                </h1>
                                <p className="text-body-md font-inter text-on-surface-variant mt-1">
                                    Active notifications and warnings across all connected devices.
                                </p>
                            </div>
                            <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-surface-container text-on-surface-variant">
                                <span className="material-symbols-outlined text-[16px] text-error-red">
                                    notification_important
                                </span>
                                <span className="text-data-mono font-mono">
                                    {alerts.length}
                                </span>
                            </div>
                        </div>

                        {loading ? (
                            <div className="flex items-center justify-center py-20">
                                <div className="w-10 h-10 rounded-full border-2 border-vibrant-violet border-t-transparent animate-spin" />
                            </div>
                        ) : alerts.length === 0 ? (
                            <div className="glass-card p-10 text-center">
                                <div className="w-16 h-16 rounded-full border border-glass-stroke flex items-center justify-center text-on-surface-variant mx-auto mb-4">
                                    <span className="material-symbols-outlined text-[32px]">check_circle</span>
                                </div>
                                <p className="text-on-surface-variant text-body-md">
                                    No alerts right now. System is running optimally.
                                </p>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {alerts.map((alert, index) => {
                                    const isNormal = alert.includes('normally');

                                    return (
                                        <div
                                            key={index}
                                            className={`
                                                backdrop-blur-xl rounded-xl p-5 flex items-start gap-4
                                                border transition-all duration-200
                                                ${isNormal
                                                    ? 'bg-electric-blue/5 border-electric-blue/20 hover:border-electric-blue/40'
                                                    : 'bg-error/5 border-error/20 hover:border-error/40'
                                                }
                                            `}
                                        >
                                            <div className={`
                                                w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0
                                                ${isNormal
                                                    ? 'bg-electric-blue/20 text-electric-blue border border-electric-blue/30'
                                                    : 'bg-error/20 text-error-red border border-error/30'
                                                }
                                            `}>
                                                <span className="material-symbols-outlined text-[20px]">
                                                    {isNormal ? 'check_circle' : 'warning'}
                                                </span>
                                            </div>

                                            <div className="flex-1 mt-1">
                                                <p className={`
                                                    font-inter text-title-md font-medium
                                                    ${isNormal ? 'text-electric-blue' : 'text-error-red'}
                                                `}>
                                                    {isNormal ? 'System Optimal' : 'Power Alert Detected'}
                                                </p>
                                                <p className="font-inter text-body-md text-on-surface-variant mt-1">
                                                    {alert}
                                                </p>
                                                <p className="text-label-caps font-inter text-on-surface-variant/50 uppercase tracking-widest mt-3">
                                                    {new Date().toLocaleString()}
                                                </p>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </main>
            </div>
        </div>
    );
}

export default AlertsPage;
